// node scripts/setup-env.js -- creates .env with random secrets (never overwrites an existing one)
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const file = path.join(__dirname, '..', '.env');
if (fs.existsSync(file)) {
  console.log('.env already exists -- leaving it untouched.');
  process.exit(0);
}
const hex = (n) => crypto.randomBytes(n).toString('hex');
const redisPw = hex(24);
const dbPw = hex(24);
const lines = [
  '# Generated by `npm run setup`. Keep this file private -- never commit or share it.',
  `JWT_SECRET=${hex(48)}`,
  `MFA_ENCRYPTION_KEY=${hex(32)}`,
  `REDIS_PASSWORD=${redisPw}`,
  `POSTGRES_PASSWORD=${dbPw}`,
  `REDIS_URL=redis://:${redisPw}@127.0.0.1:6379`,
  `DATABASE_URL=postgres://collab:${dbPw}@127.0.0.1:5432/collab_editor`,
  'PORT=8080',
  'HOST=127.0.0.1',
  'ALLOWED_ORIGINS=http://localhost:8080,http://127.0.0.1:8080',
  '# Account recovery email (configure these to enable verification and password reset):',
  '# APP_BASE_URL=https://editor.example.com',
  '# SMTP_HOST=smtp.example.com',
  '# SMTP_PORT=587',
  '# SMTP_SECURE=0',
  '# SMTP_USER=your-smtp-username',
  '# SMTP_PASS=your-smtp-password',
  '# SMTP_FROM=Collab Editor <no-reply@example.com>',
  '# For a public deployment behind Caddy/HTTPS set these instead:',
  '# NODE_ENV=production',
  '# TRUST_PROXY=1',
  '# ALLOWED_ORIGINS=https://your.domain',
  '',
];
fs.writeFileSync(file, lines.join('\n'), { mode: 0o600 });
console.log('Created .env with fresh random secrets (file mode 600).');
